            if(Input.GetKeyDown(KeyCode.W)||Input.GetKeyDown(KeyCode.UpArrow))_lane=Mathf.Min(2,_lane+1);if(Input.GetKeyDown(KeyCode.S)||Input.GetKeyDown(KeyCode.DownArrow))_lane=Mathf.Max(0,_lane-1);
            if(Input.GetKeyDown(KeyCode.Space))ActivateNitro();float throttle=(Input.GetKey(KeyCode.D)||Input.GetKey(KeyCode.RightArrow))?1:(Input.GetKey(KeyCode.A)||Input.GetKey(KeyCode.LeftArrow))?-1:0;float nitro=Time.time<_nitroUntil?4.8f:0;_speed=Mathf.MoveTowards(_speed,7.5f+throttle*3f+nitro,Time.deltaTime*(nitro>0?8f:3.5f));_distance+=_speed*Time.deltaTime;_score+=Mathf.RoundToInt(_speed*Time.deltaTime*(nitro>0?7f:4f));_invincible-=Time.deltaTime;
