            var road=SpriteObject("Road",_road,Color.white,new Vector2(-.8f,0),0);SetWidth(road,11.6f);road.transform.localScale=new Vector3(road.transform.localScale.x,road.transform.localScale.y*2.65f,1);for(int i=0;i<4;i++)Panel(new Vector2(-.8f,-3.35f+i*2.25f),new Vector2(11.4f,.055f),new Color(.2f,.85f,1,.7f),2);_player=SpriteObject("PlayerCar",_car,new Color(.25f,1f,1f),new Vector2(-4.7f,0),9);SetWidth(_player,1.7f);
            Panel(new Vector2(6.15f,0),new Vector2(1.75f,8.2f),new Color(.035f,.09f,.2f),3);Text("NEON\nRACER",new Vector2(6.15f,3.1f),3.8f,new Color(.2f,1f,1f),out _);Text("SCORE",new Vector2(6.15f,1.65f),2.2f,Color.white,out _);Text("0",new Vector2(6.15f,1.12f),3.5f,new Color(1,.82f,.2f),out _scoreText);Text("TIME",new Vector2(6.15f,.25f),2.2f,Color.white,out _);Text("60",new Vector2(6.15f,-.28f),3.5f,new Color(.3f,1f,.85f),out _timeText);Text("135 KM/H\nCOMBO x1",new Vector2(6.15f,-1.55f),2.1f,Color.white,out _speedText);Text("W/S LANE\nA/D SPEED",new Vector2(6.15f,-3f),1.8f,new Color(.72f,.82f,1),out _);Text("",new Vector2(-.65f,0),3.1f,Color.white,out _message);_resultPanel=Panel(new Vector2(-.65f,-.05f),new Vector2(7.1f,4.9f),new Color(.01f,.025f,.07f,.97f),18);Text("",new Vector2(-.65f,-.05f),2.55f,Color.white,out _preview);BuildOverlay();_audio=Track(new GameObject("RacerAudio")).AddComponent<AudioSource>();}
        void PreparePreview(){ClearMoving();_player.transform.position=ToWorld(new Vector2(-4.7f,0));_scoreText.text="0";_timeText.text="60";_speedText.text="ARCADE 08";_message.text=string.Empty;_resultPanel.SetActive(true);_preview.gameObject.SetActive(true);ArcadeRankingBoard.ShowPreview(this,_preview,_camera,"NEON RACER\nDODGE TRAFFIC • COLLECT COINS");}
